package com.erp.oa.attendance.approval;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.erp.approval.api.domain.*;
import com.erp.oa.attendance.leave.balance.AttendanceLeaveQuotaServiceTest.Harness;
class OaAttendanceApprovalQuotaRoundTest
{
 Harness h; OaAttendanceApprovalCallbackMapper mapper; OaAttendanceApprovalCallbackService service; OaAttendanceApprovalState state;
 @BeforeEach void setup(){TransactionSynchronizationManager.setActualTransactionActive(true);TransactionSynchronizationManager.setCurrentTransactionIsolationLevel(java.sql.Connection.TRANSACTION_READ_COMMITTED);h=new Harness();h.reserve();h.request.approvalInstanceId=90L;h.request.rowVersion=3L;mapper=mock(OaAttendanceApprovalCallbackMapper.class);service=new OaAttendanceApprovalCallbackService(mapper,h.json,h.service);state=new OaAttendanceApprovalState();state.setBusinessId(10L);state.setUserId(11L);state.setShopId(20L);state.setStatus("PENDING");state.setBusinessRound(1);state.setApprovalInstanceId(90L);state.setRowVersion(3L);when(mapper.selectLeaveForUpdate(10L)).thenReturn(state);when(mapper.selectLeave(10L)).thenReturn(state);when(mapper.updateLeaveDecision(eq(10L),anyString(),anyLong(),anyString(),anyString(),any())).thenAnswer(i->{state.setStatus(i.getArgument(3));state.setLastApprovalEventKey(i.getArgument(4));h.request.status=i.getArgument(3);return 1;});}
 @AfterEach void clear(){TransactionSynchronizationManager.clear();}
 ApprovalBusinessCallbackRequest callback(String action,String target,String key){var r=new ApprovalBusinessCallbackRequest();r.setEventKey(key);r.setInstanceId(90L);r.setBusinessCode("OA_ATTENDANCE_LEAVE");r.setBusinessId("10");r.setBusinessRound(1);r.setAction(action);r.setPayload("{\"targetStatus\":\""+target+"\"}");return r;}
 ApprovalBusinessActionValidationRequest validation() throws Exception{var r=new ApprovalBusinessActionValidationRequest();r.setInstanceId(90L);r.setBusinessCode("OA_ATTENDANCE_LEAVE");r.setBusinessId("10");r.setBusinessRound(1);r.setAction("APPROVE");r.setApplicantUserId(11L);r.setAnchorDeptId(20L);var s=h.json.createObjectNode();s.put("leaveRequestId",10L);s.put("shopId",20L);s.put("attachmentCount",0);s.put("attachmentRequired",false);s.put("requestedDays",h.request.requestedDays.toPlainString());s.put("quotaUnits",h.request.quotaUnits.toString());s.set("quotaPolicySnapshot",h.json.valueToTree(h.request.quotaPolicySnapshot));r.setBusinessSnapshot(h.json.writeValueAsString(s));return r;}
 long reserved(){return h.buckets.stream().mapToLong(b->b.reservedUnits).sum();}long consumed(){return h.buckets.stream().mapToLong(b->b.consumedUnits).sum();}
 @Test void matchingApprovalConsumesAndReplayCannotSpendAgain(){var c=callback("APPROVE","APPROVED","approve-one");assertThat(service.apply(c).getAccepted()).isTrue();assertThat(service.apply(c).getCode()).isEqualTo("IDEMPOTENT");assertThat(reserved()).isZero();assertThat(consumed()).isEqualTo(420_000_000L);assertThat(h.ledger).hasSize(4);}
 @Test void oldRoundCannotTouchReservation(){var c=callback("APPROVE","APPROVED","old-round");c.setBusinessRound(0);assertThat(service.apply(c).getAccepted()).isFalse();assertThat(reserved()).isEqualTo(420_000_000L);assertThat(h.ledger).hasSize(2);}
 @Test void pendingTerminationReleasesInsteadOfRefundingUnspentCredit(){assertThat(service.apply(callback("TERMINATE","TERMINATED","pending-stop")).getAccepted()).isTrue();assertThat(reserved()).isZero();assertThat(consumed()).isZero();assertThat(h.allocations).allMatch(a->a.status.equals("RELEASED"));}
 @Test void approvedTerminationRefundsOnlyOriginalConsumption(){service.apply(callback("APPROVE","APPROVED","approve"));assertThat(service.apply(callback("TERMINATE","TERMINATED","after-approved")).getAccepted()).isTrue();assertThat(consumed()).isZero();assertThat(h.allocations).allMatch(a->a.status.equals("REFUNDED"));}
 @Test void rejectionAndWithdrawalUseOriginalAllocations(){assertThat(service.apply(callback("WITHDRAW","WITHDRAWN","withdraw")).getAccepted()).isTrue();assertThat(reserved()).isZero();assertThat(h.allocations).allMatch(a->a.status.equals("RELEASED"));}
 @Test void businessCasFailureMustThrowForOwnerTransactionRollback(){when(mapper.updateLeaveDecision(eq(10L),anyString(),anyLong(),anyString(),anyString(),any())).thenReturn(0);assertThatThrownBy(()->service.apply(callback("APPROVE","APPROVED","cas-failed"))).hasMessageContaining("CALLBACK_CONCURRENT_UPDATE");verify(mapper,never()).invalidateLeaveDayResults(anyLong(),any());}
 @Test void exactPolicyDaysAndUnitsPassPreApprovalValidation() throws Exception{assertThat(service.validateAction(validation()).getAccepted()).isTrue();}
 @Test void changedPolicyDaysOrUnitsFailPreApproval() throws Exception{for(String field:java.util.List.of("requestedDays","quotaUnits","quotaPolicySnapshot")){var r=validation();var s=(com.fasterxml.jackson.databind.node.ObjectNode)h.json.readTree(r.getBusinessSnapshot());if(field.equals("quotaPolicySnapshot"))((com.fasterxml.jackson.databind.node.ObjectNode)s.get(field)).put("ruleVersion",2);else s.put(field,"2");r.setBusinessSnapshot(h.json.writeValueAsString(s));assertThat(service.validateAction(r).getCode()).isEqualTo("QUOTA_SNAPSHOT_CHANGED");}assertThat(reserved()).isEqualTo(420_000_000L);}
}
